package cn.breezeth.kaleidoscope_grilling;
import net.minecraft.core.BlockPos;import net.minecraft.core.HolderLookup;import net.minecraft.nbt.CompoundTag;import net.minecraft.world.entity.item.FallingBlockEntity;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.AABB;
public final class OilPressBlockEntity extends BlockEntity{public static final int MAX_CAKES=4,REQUIRED_PROGRESS=8;private int cakes,progress,residue;public OilPressBlockEntity(BlockPos p,BlockState s){super(ModBlockEntities.OIL_PRESS.get(),p,s);}public int cakes(){return cakes;}public int progress(){return progress;}public int residue(){return residue;}public boolean addCake(){if(cakes>=MAX_CAKES)return false;cakes++;sync();return true;}public int takeResidue(){int r=residue;residue=0;sync();return r;}public boolean impact(int amount){if(cakes==0||amount<=0)return false;progress=Math.min(REQUIRED_PROGRESS,progress+amount);if(progress>=REQUIRED_PROGRESS)tryFinish();sync();return true;}public static void serverTick(Level level,BlockPos pos,BlockState state,OilPressBlockEntity press){AABB area=new AABB(pos.getX(),pos.getY()+1,pos.getZ(),pos.getX()+1,pos.getY()+2.25,pos.getZ()+1);for(FallingBlockEntity f:level.getEntitiesOfClass(FallingBlockEntity.class,area)){if(f.getPersistentData().getBoolean("GrillingPressImpact")||f.fallDistance<1)continue;int amount=PressImpactRegistry.progress(f.getBlockState().getBlock());if(amount>0&&press.impact(amount))f.getPersistentData().putBoolean("GrillingPressImpact",true);}}private void tryFinish(){BigVatBlockEntity vat=findVat();if(vat==null||vat.buckets()+cakes>BigVatBlockEntity.CAPACITY_BUCKETS||!vat.canAccept("canola"))return;if(vat.insert("canola",cakes)){residue+=cakes;cakes=0;progress=0;}}private BigVatBlockEntity findVat(){if(level==null)return null;for(BlockPos p:BlockPos.betweenClosed(worldPosition.offset(-2,-1,-2),worldPosition.offset(2,1,2)))if(level.getBlockEntity(p)instanceof BigVatBlockEntity v&&v.canAccept("canola"))return v;return null;}private void sync(){setChanged();if(level!=null)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}@Override protected void saveAdditional(CompoundTag t,HolderLookup.Provider r){super.saveAdditional(t,r);t.putInt("Cakes",cakes);t.putInt("Progress",progress);t.putInt("Residue",residue);}@Override protected void loadAdditional(CompoundTag t,HolderLookup.Provider r){super.loadAdditional(t,r);cakes=Math.max(0,Math.min(MAX_CAKES,t.getInt("Cakes")));progress=Math.max(0,Math.min(REQUIRED_PROGRESS,t.getInt("Progress")));residue=Math.max(0,t.getInt("Residue"));}}
